#[derive(Clone, Copy, Debug, Hash, PartialEq, Eq)]
pub enum DamageType {
    Physical,
    Fire,
    Cold,
    Air,
    Lightning,
    Poison,
    Holy,
    Shadow,
    Necrotic,
    Arcane,
}

impl DamageType {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Physical => "PHYSICAL",
            Self::Fire => "FIRE",
            Self::Cold => "COLD",
            Self::Air => "AIR",
            Self::Lightning => "LIGHTNING",
            Self::Poison => "POISON",
            Self::Holy => "HOLY",
            Self::Shadow => "SHADOW",
            Self::Necrotic => "NECROTIC",
            Self::Arcane => "ARCANE",
        }
    }

    pub fn from_wire(value: &str) -> Self {
        match value.trim().to_ascii_uppercase().as_str() {
            "FIRE" => Self::Fire,
            "COLD" => Self::Cold,
            "AIR" => Self::Air,
            "LIGHTNING" => Self::Lightning,
            "POISON" => Self::Poison,
            "HOLY" => Self::Holy,
            "SHADOW" => Self::Shadow,
            "NECROTIC" => Self::Necrotic,
            "ARCANE" => Self::Arcane,
            _ => Self::Physical,
        }
    }
}

