pub fn default_hit_capsule() -> (f32, f32) {
    (DEFAULT_HIT_RADIUS, DEFAULT_HIT_HEIGHT)
}

pub fn default_new_player_spawn() -> (f32, f32, f32) {
    let (hit_radius, hit_height) = default_hit_capsule();
    resolve_world_spawn_position(None, SPAWN_X, SPAWN_Z, hit_radius, hit_height)
}

pub fn new_player_spawn_state(player_id: Identity, now: Timestamp) -> (f32, f32, f32, PlayerState) {
    let (spawn_x, spawn_y, spawn_z) = default_new_player_spawn();
    let state = new_player_state(player_id, now);
    (spawn_x, spawn_y, spawn_z, state)
}

pub fn clear_player_combat_state(ctx: &ReducerContext, identity: Identity) {
    clear_statuses_for_identity(ctx, identity);
    clear_active_radial_effects_for_owner(ctx, identity);
    clear_combat_engagement_for_identity(ctx, identity);
    clear_combat_stacking_passive_runtime_for_identity(ctx, identity);
    clear_potential_state_for_owner(ctx, identity);
    clear_blight_empowered_action_runtime(ctx, identity);
}

pub fn new_player_state(player_id: Identity, now: Timestamp) -> PlayerState {
    new_alive_player_state(
        player_id,
        false,
        DEFAULT_MAX_HP,
        DEFAULT_MAX_HP,
        DEFAULT_HIT_RADIUS,
        DEFAULT_HIT_HEIGHT,
        now,
    )
}

pub fn reset_player_state_to_spawn(state: &mut PlayerState, now: Timestamp) {
    state.alive = true;
    state.eliminated = false;
    state.hp = state.max_hp;
    state.hit_radius = DEFAULT_HIT_RADIUS;
    state.hit_height = DEFAULT_HIT_HEIGHT;
    state.movement_blocked = false;
    state.move_speed_multiplier = 1.0;
    state.movement_context_tick = 0;
    state.voluntary_move_epoch = 0;
    state.last_voluntary_move_input_tick = 0;
    state.last_strike_id = String::new();
    state.last_strike_at = Timestamp::UNIX_EPOCH;
    mark_respawn_ready(state, now);
}

pub(crate) fn sync_player_state_derived_stats(
    ctx: &ReducerContext,
    owner: Identity,
    derived: crate::derived_stats::DerivedCombatStats,
) -> bool {
    let Some(mut state) = ctx.db.player_state().player_id().find(owner) else {
        return false;
    };
    if state.is_dummy {
        return false;
    }

    let next_max_hp = derived.max_hp.max(1);
    let previous_max_hp = state.max_hp.max(1);
    if previous_max_hp == next_max_hp {
        return false;
    }

    let was_full = state.hp >= previous_max_hp;
    let missing_hp = previous_max_hp.saturating_sub(state.hp.max(0));
    state.max_hp = next_max_hp;
    if was_full {
        state.hp = next_max_hp;
    } else {
        state.hp = next_max_hp.saturating_sub(missing_hp).clamp(0, next_max_hp);
    }

    ctx.db.player_state().player_id().update(state);
    true
}

pub fn new_dummy_player_state(
    player_id: Identity,
    now: Timestamp,
    max_hp: i32,
    hit_radius: f32,
    hit_height: f32,
) -> PlayerState {
    new_alive_player_state(player_id, true, max_hp, max_hp, hit_radius, hit_height, now)
}

fn new_alive_player_state(
    player_id: Identity,
    is_dummy: bool,
    hp: i32,
    max_hp: i32,
    hit_radius: f32,
    hit_height: f32,
    now: Timestamp,
) -> PlayerState {
    PlayerState {
        player_id,
        is_dummy,
        alive: true,
        eliminated: false,
        hp,
        max_hp,
        hit_radius,
        hit_height,
        movement_blocked: false,
        move_speed_multiplier: 1.0,
        movement_context_tick: 0,
        voluntary_move_epoch: 0,
        last_voluntary_move_input_tick: 0,
        respawn_at: respawn_ready_at(now),
        last_strike_id: String::new(),
        last_strike_at: Timestamp::UNIX_EPOCH,
    }
}

#[table(accessor = player_event, public)]
pub struct PlayerEvent {
    #[primary_key]
    #[auto_inc]
    pub event_id: u64,
    pub event_type: String,
    #[index(btree)]
    pub player_id: Identity,
    pub pos_x: f32,
    pub pos_y: f32,
    pub pos_z: f32,
    pub created_at: Timestamp,
    // Keep a micros mirror because SpacetimeDB pruning needs a btree-indexed scalar;
    // the Timestamp payload is retained for client/event readability.
    #[index(btree)]
    pub created_at_micros: i64,
}

