/// Tracks confirmed HP damage for boomerang projectiles that heal only after completing
/// their return. Keeping this separate from collision state lets the normal queued-damage
/// pass remain the sole authority for the amount actually dealt.
#[table(accessor = projectile_return_heal_runtime)]
pub struct ProjectileReturnHealRuntime {
    #[primary_key]
    pub projectile_instance_id: String,
    #[index(btree)]
    pub caster: Identity,
    pub accumulated_damage: i32,
    pub returned_to_caster: bool,
}

pub(crate) fn register_projectile_return_heal(
    ctx: &ReducerContext,
    projectile_instance_id: &str,
    caster: Identity,
) {
    ctx.db
        .projectile_return_heal_runtime()
        .insert(ProjectileReturnHealRuntime {
            projectile_instance_id: projectile_instance_id.to_string(),
            caster,
            accumulated_damage: 0,
            returned_to_caster: false,
        });
}

pub(crate) fn mark_projectile_returned_for_heal(
    ctx: &ReducerContext,
    projectile_instance_id: &str,
) -> bool {
    let Some(mut runtime) = ctx
        .db
        .projectile_return_heal_runtime()
        .projectile_instance_id()
        .find(projectile_instance_id.to_string())
    else {
        return false;
    };
    runtime.returned_to_caster = true;
    let caster = runtime.caster;
    ctx.db
        .projectile_return_heal_runtime()
        .projectile_instance_id()
        .update(runtime);

    // Ensures the post-projectile effect pass runs even when the return frame had no enemy contact.
    queue_effects(
        ctx,
        vec![EffectPacket::Heal {
            amount: 0,
            source: caster,
            target: caster,
            spell_id: projectile_instance_id.to_string(),
            target_audience: TargetAudience::SelfOnly,
        }],
    );
    true
}

pub(crate) fn clear_projectile_return_heal(ctx: &ReducerContext, projectile_instance_id: &str) {
    ctx.db
        .projectile_return_heal_runtime()
        .projectile_instance_id()
        .delete(projectile_instance_id.to_string());
}

pub(crate) fn sync_combat_projectile_definitions(ctx: &ReducerContext) {
    let expected: HashSet<_> = COMBAT_PROJECTILE_DEFINITIONS
        .iter()
        .map(|definition| definition.projectile_id.to_string())
        .collect();

    for definition in COMBAT_PROJECTILE_DEFINITIONS {
        let row = CombatProjectileDefinition {
            projectile_id: definition.projectile_id.to_string(),
            speed: definition.speed,
            max_distance: definition.max_distance,
            radius: definition.radius,
            spawn_forward: definition.spawn_forward,
            spawn_height: definition.spawn_height,
            aim_height_scale: definition.aim_height_scale,
            requires_initial_line_of_sight: definition.requires_initial_line_of_sight,
            update_interval_seconds: definition.update_interval_seconds,
        };
        if ctx
            .db
            .combat_projectile_definition()
            .projectile_id()
            .find(row.projectile_id.clone())
            .is_some()
        {
            ctx.db
                .combat_projectile_definition()
                .projectile_id()
                .update(row);
        } else {
            ctx.db.combat_projectile_definition().insert(row);
        }
    }

    let stale: Vec<_> = ctx
        .db
        .combat_projectile_definition()
        .iter()
        .map(|row| row.projectile_id)
        .filter(|projectile_id| !expected.contains(projectile_id))
        .collect();
    for projectile_id in stale {
        ctx.db
            .combat_projectile_definition()
            .projectile_id()
            .delete(projectile_id);
    }
}

pub(crate) fn combat_projectile_definition_for_id(
    ctx: &ReducerContext,
    projectile_id: &str,
) -> Option<CombatProjectileDefinition> {
    ctx.db
        .combat_projectile_definition()
        .projectile_id()
        .find(projectile_id.trim().to_ascii_uppercase())
}

pub fn is_in_combat(ctx: &ReducerContext, owner: Identity, now: Timestamp) -> bool {
    ctx.db
        .combat_engagement()
        .owner()
        .find(owner)
        .is_some_and(|row| now < row.expires_at)
}

pub fn mark_harmful_combat_action(
    ctx: &ReducerContext,
    source: Identity,
    target: Identity,
    now: Timestamp,
    reason: &str,
) {
    if source == Identity::ZERO || target == Identity::ZERO || source == target {
        return;
    }
    if !players_share_world_context(ctx, source, target) {
        return;
    }

    mark_identity_in_combat(ctx, source, now, reason, source, target);
    mark_identity_in_combat(ctx, target, now, reason, source, target);
}

fn mark_helpful_combat_assist(
    ctx: &ReducerContext,
    source: Identity,
    target: Identity,
    now: Timestamp,
) {
    if source == Identity::ZERO || target == Identity::ZERO || source == target {
        return;
    }
    if !players_share_world_context(ctx, source, target) {
        return;
    }
    if !is_in_combat(ctx, target, now) {
        return;
    }

    mark_identity_in_combat(
        ctx,
        source,
        now,
        COMBAT_REASON_HELPFUL_ASSIST,
        source,
        target,
    );
}

fn mark_identity_in_combat(
    ctx: &ReducerContext,
    owner: Identity,
    now: Timestamp,
    reason: &str,
    source: Identity,
    target: Identity,
) {
    if owner == Identity::ZERO {
        return;
    }
    let Some(state) = ctx.db.player_state().player_id().find(owner) else {
        return;
    };
    if !state.alive {
        return;
    }

    let requested_expires_at = now + DEFAULT_COMBAT_ENGAGEMENT_DURATION;
    let requested_expires_at_micros = timestamp_to_micros(requested_expires_at);
    if let Some(mut row) = ctx.db.combat_engagement().owner().find(owner) {
        if now >= row.expires_at {
            row.entered_at = now;
        }
        row.last_activity_at = now;
        if requested_expires_at > row.expires_at {
            row.expires_at = requested_expires_at;
            row.expires_at_micros = requested_expires_at_micros;
        }
        row.reason = reason.to_string();
        row.source = source;
        row.target = target;
        ctx.db.combat_engagement().owner().update(row);
    } else {
        ctx.db.combat_engagement().insert(CombatEngagement {
            owner,
            entered_at: now,
            last_activity_at: now,
            expires_at: requested_expires_at,
            expires_at_micros: requested_expires_at_micros,
            reason: reason.to_string(),
            source,
            target,
        });
    }
}

pub fn expire_combat_engagements(ctx: &ReducerContext, now: Timestamp) {
    ctx.db
        .combat_engagement()
        .expires_at_micros()
        .delete(..=timestamp_to_micros(now));
}

pub fn clear_combat_engagement_for_identity(ctx: &ReducerContext, identity: Identity) {
    if ctx.db.combat_engagement().owner().find(identity).is_some() {
        ctx.db.combat_engagement().owner().delete(identity);
    }
}

