    #[test]
    fn immolation_six_second_stack_group_counts_all_pending_ticks_together() {
        let start = Timestamp::UNIX_EPOCH;
        let expires_at = start + Duration::from_secs(6);
        assert_eq!(
            immolation_remaining_tick_count(
                start + Duration::from_secs(1),
                expires_at,
                Duration::from_secs(1),
                start,
            ),
            6
        );
        assert_eq!(
            immolation_remaining_tick_count(
                start + Duration::from_secs(7),
                expires_at,
                Duration::from_secs(1),
                start,
            ),
            0
        );
    }

    fn test_status_effect(
        target: Identity,
        payload: StatusPayload,
        now: Timestamp,
        expires_at: Timestamp,
    ) -> StatusEffect {
        let group = format!("{}_GROUP", payload.kind().as_str());
        new_status_effect(
            target,
            target,
            StatusPolarity::Debuff,
            &group,
            10,
            StackPolicy::Refresh,
            "TEST_STATUS",
            payload,
            now,
            expires_at,
            String::new(),
        )
    }

    fn status_runtime_view(
        effects: Vec<StatusEffect>,
        alive_targets: &[Identity],
        now: Timestamp,
    ) -> StatusRuntimeView {
        let alive_targets: HashSet<Identity> = alive_targets.iter().copied().collect();
        StatusRuntimeView::from_status_effects(effects, &alive_targets, now)
    }

