    fn broad_debuff_removal_excludes_active_radial_projections() {
        assert!(!status_matches_removal_filter_values(
            "DEBUFF",
            "MAGIC|POISON",
            Some(StatusPolarity::Debuff),
            &[],
            true,
            false,
        ));
    }

    #[test]
    fn rime_protection_excludes_buffs_and_debuffs_from_ability_removal_filters() {
        assert!(!status_matches_removal_filter_values(
            "DEBUFF",
            "BLEED",
            Some(StatusPolarity::Debuff),
            &[StatusDispelType::Bleed],
            false,
            true,
        ));
        assert!(!status_matches_removal_filter_values(
            "BUFF",
            "MAGIC",
            Some(StatusPolarity::Buff),
            &[StatusDispelType::Magic],
            false,
            true,
        ));
    }

    #[test]
    fn standard_arrow_projectile_definition_is_fast_and_physical() {
        let arrow = COMBAT_PROJECTILE_DEFINITIONS
            .iter()
            .find(|definition| definition.projectile_id == "ARROW_STANDARD")
            .expect("ARROW_STANDARD projectile definition should exist");

        assert!(arrow.speed >= 35.0);
        assert!(arrow.max_distance > 0.0);
        assert!((0.05..=0.20).contains(&arrow.radius));
        assert_eq!(arrow.update_interval_seconds, 0.10);
        assert!(arrow.requires_initial_line_of_sight);
    }

